#!/bin/bash
# DRYRUN finish2: updated telemetry checker (D-HOP-04 closed schemas + TS7) and offline-seed proof on Chromium, fresh 22eac98 worktree (tools/node_modules reinstalled).
set -u; export PATH=/usr/local/bin:/usr/bin:/bin; V=/workspace/egg-farm-studio/qa/v5-saves; LOCK=/workspace/egg-farm-studio/.browser-test.lock; WT=/workspace/egg-farm-studio/qa/wt-v5saves-22eac98; GIT=/workspace/egg-farm-studio/game
git -C "$GIT" worktree add --detach "$WT" 22eac98c75b9e82944f34a1feb77830521f34aee >/dev/null 2>&1; (cd "$WT" && npm ci --no-audit --no-fund >/dev/null 2>&1 && npm run build:qa >/dev/null 2>&1 && npm run build:html >/dev/null 2>&1); echo "build $(date '+%T') porcelain=$(git -C $WT status --porcelain | wc -l) id=$(grep -o 'm4.1+[0-9a-z+]*' $WT/dist-html/egg-farm.html | sort -u)"
T=$V/dryrun/telemetry-DRYRUN-v2-22eac98; rm -rf $T; MIDS=$(cd "$WT" && node -e "const M=require('./src/config/balance.json').m4.milestones;console.log([...M.hens.map(m=>'hens:'+m.level),...M.grades.map(g=>'grade:'+g.level),...M.balanced.map((_,i)=>'balanced:'+(i+1))].join(','))")
echo "telemetry v2 start $(date '+%T %Z') mids=$MIDS"; flock -w 1500 "$LOCK" bash -c "echo lock-acquired \$(date +%T); timeout 600 node $V/scripts/telemetry-check.mjs --html $WT/dist-html/egg-farm.html --engine chromium --port 5961 --out $T --expect-build m4.1+22eac98 --milestone-ids $MIDS --qa-dir $WT/dist-qa" > $T.log 2>&1; echo "telemetry v2 exit $? $(date '+%T')"
P=$V/dryrun/offline-seed-proof-DRYRUN; rm -rf $P; flock -w 1500 "$LOCK" bash -c "echo lock-acquired \$(date +%T); timeout 300 node $V/scripts/offline-seed-proof.mjs --html $WT/dist-html/egg-farm.html --port 5962 --out $P --engine chromium" > $P.log 2>&1; echo "proof exit $? $(date '+%T')"
git -C "$WT" status --porcelain | grep -q . && echo "KEEP dirty $WT" || git -C "$GIT" worktree remove --force "$WT"; echo "ALL DONE $(date '+%T')"
